import http.client,pathlib,hashlib,os
def download(port,path,destination,expected_sha256):
    destination=pathlib.Path(destination)
    if destination.is_absolute() or '..' in destination.parts:raise ValueError('workspace-relative output required')
    temporary=destination.with_name(destination.name+'.part')
    if temporary.exists():raise ValueError('temporary path already exists')
    c=http.client.HTTPConnection('127.0.0.1',port,timeout=2)
    try:
        c.request('GET',path);r=c.getresponse()
        if r.status!=200:raise ValueError('HTTP failure')
        data=r.read()
        if hashlib.sha256(data).hexdigest()!=expected_sha256:raise ValueError('digest mismatch')
        temporary.write_bytes(data);os.replace(temporary,destination)
    finally:
        c.close()
        if temporary.exists():temporary.unlink()
